	public string DefineDayeOfWeek()
	{
		return DateTime.Now.DayOfWeek.ToString() switch
		{
			"Saturday" => "7", 
			"Sunday" => "1", 
			"Monday" => "2", 
			"Tuesday" => "3", 
			"Wednesday" => "4", 
			"Thursday" => "5", 
			"Friday" => "6", 
			_ => null, 
		};
	}

	public string ConvertNumToDayeOfWeek(int num)
	{
		return num switch
		{
			7 => Labels.Saturday, 
			1 => Labels.Sunday, 
			2 => Labels.Monday, 
			3 => Labels.Tuesday, 
			4 => Labels.Wednesday, 
			5 => Labels.Thursday, 
			6 => Labels.Friday, 
			_ => null, 
		};
	}

