	public static string HexToColor(string hexColor)
	{
		string result = "";
		try
		{
			if (string.IsNullOrWhiteSpace(hexColor))
			{
				return null;
			}
			if (hexColor.IndexOf('#') != -1)
			{
				hexColor = hexColor.Replace("#", "");
			}
			string text = "00";
			string text2 = "00";
			string text3 = "00";
			if (hexColor.Length == 6)
			{
				text = hexColor.Substring(0, 2);
				text2 = hexColor.Substring(2, 2);
				text3 = hexColor.Substring(4, 2);
			}
			else if (hexColor.Length == 3)
			{
				text = hexColor[0].ToString() + hexColor[0];
				text2 = hexColor[1].ToString() + hexColor[1];
				text3 = hexColor[2].ToString() + hexColor[2];
			}
			result = "$00" + text3.ToString() + text2.ToString() + text.ToString();
		}
		catch (Exception e)
		{
			ErrorSignal.FromCurrentContext().Raise(e);
		}
		return result;
	}

	public string TColorToHex(string TColor)
	{
		//IL_0016: Unknown result type (might be due to invalid IL or missing references)
		//IL_001b: Unknown result type (might be due to invalid IL or missing references)
		//IL_001c: Unknown result type (might be due to invalid IL or missing references)
		//IL_001d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0029: Unknown result type (might be due to invalid IL or missing references)
		if (TColor.StartsWith("#"))
		{
			return TColor;
		}
		string text = "";
		Color val = ConvertColor.ColorNameStringToColor(TColor);
		if (val != Color.Empty)
		{
			text = ConvertColor.ColorToHexString(val);
		}
		if (text == "")
		{
			try
			{
				string text2 = TColor.Substring(3, 2);
				string text3 = TColor.Substring(5, 2);
				string text4 = TColor.Substring(7, 2);
				text = "#" + text4 + text3 + text2;
			}
			catch (Exception e)
			{
				ErrorSignal.FromCurrentContext().Raise(e);
				text = "";
			}
		}
		return text;
	}

