	public JsonResult DownloadMultiFiles(string fileIds)
	{
		int data = 0;
		string message = "";
		CommonResultStatusViewModel status = CommonResultStatusViewModel.Success;
		if (!string.IsNullOrWhiteSpace(fileIds))
		{
			try
			{
				int userId = UserLogin.CurrentUser.UserId;
				if (fileIds.EndsWith(","))
				{
					fileIds = fileIds.TrimEnd(new char[1] { ',' });
				}
				if (fileIds.StartsWith(","))
				{
					fileIds = fileIds.TrimStart(new char[1] { ',' });
				}
				string[] array = fileIds.Split(new char[1] { ',' });
				if (array != null && array.Length != 0)
				{
					FilesManager filesManager = new FilesManager();
					string text = filesManager.SetNameDirectory(userId);
					if (filesManager.CreateDirectory(text))
					{
						string text2 = string.Format("Zip_{0}.zip", DateTime.Now.ToString("yyyyMMddHHmmss"));
						string text3 = HttpContext.Current.Server.MapPath(text + "/" + text2);
						string[] array2 = new string[array.Length];
						int num = 0;
						int num2 = array.Length;
						string[] array3 = array;
						foreach (string text4 in array3)
						{
							if (string.IsNullOrWhiteSpace(text4))
							{
								continue;
							}
							string text5 = "";
							string text6 = "";
							int result = 0;
							int.TryParse(text4, out result);
							if (result == 0)
							{
								continue;
							}
							text5 = GetFilePath(result, idUrlEncode: false);
							if (string.IsNullOrWhiteSpace(text5))
							{
								continue;
							}
							if (result != 0)
							{
								PrintLog.InsertPrintLog(result, 550, 3);
							}
							try
							{
								if (System.IO.File.Exists(text5))
								{
									string fileName = Path.GetFileName(text5);
									text6 = HttpContext.Current.Server.MapPath(text + "/" + fileName);
									if (array2 != null && array2.Length != 0)
									{
										string[] array4 = array2;
										foreach (string text7 in array4)
										{
											if (!string.IsNullOrWhiteSpace(text7) && text7.ToLower() == text6.ToLower() && !string.IsNullOrWhiteSpace(fileName))
											{
												string text8 = "." + fileName.Split(new char[1] { '.' })[^1];
												string text9 = fileName;
												text9 = text9.Replace(text8, "") + "-" + DateTime.Now.ToString("yyyyMMddHHmmss") + text8.ToLower();
												text6 = HttpContext.Current.Server.MapPath(text + "/" + text9);
											}
										}
									}
									System.IO.File.Copy(text5, text6, overwrite: true);
									string text10 = text5.Replace("/" + fileName, "");
									text10 = text10.Replace("\\" + fileName, "");
									DirectoryInfo directoryInfo = new DirectoryInfo(text10);
									FileInfo[] files = directoryInfo.GetFiles();
									for (int j = 0; j < files.Length; j++)
									{
										files[j].Delete();
									}
									DirectoryInfo[] directories = directoryInfo.GetDirectories();
									for (int j = 0; j < directories.Length; j++)
									{
										directories[j].Delete(recursive: true);
									}
									if (System.IO.Directory.Exists(text10))
									{
										System.IO.Directory.Delete(text10);
									}
								}
							}
							catch (Exception e)
							{
								ErrorSignal.FromCurrentContext().Raise(e);
							}
							if (!string.IsNullOrWhiteSpace(text6))
							{
								array2[num] = text6;
								num++;
								int count = num * 100 / num2;
								ProgressHub.SendMessage("ok", count, userId);
							}
						}
						if (Enumerable.Any<string>((IEnumerable<string>)array2))
						{
							using (ZipFile zipFile = new ZipFile())
							{
								zipFile.UseUnicodeAsNecessary = true;
								zipFile.AddFiles(array2, "");
								zipFile.Save(text3);
							}
							array3 = array2;
							foreach (string text11 in array3)
							{
								if (string.IsNullOrWhiteSpace(text11))
								{
									continue;
								}
								try
								{
									try
									{
										if (System.IO.File.Exists(text11))
										{
											System.IO.File.Delete(text11);
										}
									}
									catch (Exception e2)
									{
										ErrorSignal.FromCurrentContext().Raise(e2);
									}
								}
								catch (Exception e3)
								{
									ErrorSignal.FromCurrentContext().Raise(e3);
								}
							}
							data = 1;
							message = text3;
							status = CommonResultStatusViewModel.Success;
						}
					}
				}
			}
			catch (Exception ex)
			{
				ErrorSignal.FromCurrentContext().Raise(ex);
				data = 0;
				message = Messages.msgErrorRunFunction + " (" + ex.Message + ")";
				status = CommonResultStatusViewModel.Error;
			}
		}
		CommonResultViewModel<int> data2 = new CommonResultViewModel<int>
		{
			Data = data,
			Message = message,
			Status = status
