			}
			if (!UserLogin.IsUserAccess("frmCompanyI", "actNotShowcmpOrdAmnt", UserLogin.CurrentUser))
			{
				if (cRMspReturnCmpAccountingSummary_Result.AllSaleOrdercnt != 0)
				{
					companyAccountingSummaryViewModel.Sales = cRMspReturnCmpAccountingSummary_Result.AllSaleOrdercnt + "lblCmpAccSummaryOrder".OrderLabels() + $"{cRMspReturnCmpAccountingSummary_Result.AllSaleOrder:N2}";
				}
				else
				{
					companyAccountingSummaryViewModel.Sales = "lblCmpAccSummaryOrderNull".OrderLabels();
				}
			}
			else
			{
				companyAccountingSummaryViewModel.Sales = "lblCmpAccSummaryOrderNull".OrderLabels();
			}
			if (!UserLogin.IsUserAccess("frmCompanyI", "actNotShowcmpRetOrdAmnt", UserLogin.CurrentUser))
			{
				if (cRMspReturnCmpAccountingSummary_Result.AllRetOrdercnt != 0)
				{
