				}
				else
				{
					companyAccountingSummaryViewModel.ReturnSales = "lblCmpAccSummaryRetOrderNull".OrderLabels();
				}
			}
			else
			{
				companyAccountingSummaryViewModel.ReturnSales = "lblCmpAccSummaryRetOrderNull".OrderLabels();
			}
