			}
			decimal result2 = default(decimal);
			string text = "";
			decimal.TryParse(cRMspReturnCmpAccountingSummary_Result.CmpMnBgCompanyRemain.ToString(), out result2);
			if (result2 != 0m)
			{
				text = " (" + $"{result2:N2}" + ")";
			}
			if (!UserLogin.IsUserAccess("frmCompanyI", "actNotShowcmpOrdRemain", UserLogin.CurrentUser))
			{
				CRMspSelectCrmsysSetting_Result cRMspSelectCrmsysSetting_Result = SysSeting.Get();
