						cRMspSelectCrmsysSetting_Result.CmpAccFromLink.GetValueOrDefault();
					}
					cRMspSelectCrmsysSetting_Result.LinkAccSystemId.GetValueOrDefault();
				}
				decimal? allBuyOrder = cRMspReturnCmpAccountingSummary_Result.AllPayRemain;
				if (!((allBuyOrder.GetValueOrDefault() == default(decimal)) & allBuyOrder.HasValue))
				{
					companyAccountingSummaryViewModel.Remained = Labels.lblCmpAccSummaryRemain + $"{cRMspReturnCmpAccountingSummary_Result.AllPayRemain:N2}" + text;
				}
				else
				{
					companyAccountingSummaryViewModel.Remained = Labels.lblCmpAccSummaryRemainNull;
				}
			}
			else
			{
				companyAccountingSummaryViewModel.Remained = Labels.lblCmpAccSummaryRemainNull;
			}
		}
		return companyAccountingSummaryViewModel;
	}

