	[HttpGet]
	[AjaxOnly]
	public JsonResult GetCompanyPasswordMoreInfo(int companyId, string inputPassword, int mode)
	{
		if (!UserLogin.IsUserAccess("frmDefineCompany", "actShowCmpPassword"))
		{
			return Json(new
			{
				message = Messages.ErrorNotAccess,
				data = string.Empty
			}, JsonRequestBehavior.AllowGet);
		}
		CRMspSelectCompanyById_Result companyById = CRMIdeal.Classes.Helper.Company.GetCompanyById(companyId);
		if (companyById == null || string.IsNullOrEmpty(companyById.cmpPassword))
		{
			return Json(new
			{
				data = inputPassword
			}, JsonRequestBehavior.AllowGet);
		}
		string obj = ((!string.IsNullOrEmpty(inputPassword)) ? XorCipher.EncryptByPublicKey(inputPassword) : null);
		string text = ((!string.IsNullOrEmpty(companyById.cmpPassword)) ? XorCipher.DecryptByPublicKey(companyById.cmpPassword) : null);
		bool num = obj == companyById.cmpPassword;
		bool flag = inputPassword == companyById.cmpPassword;
		if (!num && !flag)
		{
			return Json(new
			{
				data = inputPassword
			}, JsonRequestBehavior.AllowGet);
		}
		return Json(new
		{
			data = ((mode == 1) ? text : companyById.cmpPassword)
		}, JsonRequestBehavior.AllowGet);
	}

