	public string ChkBeforeSubmitCnvs(CrmConversationLanguageViewModel conversation, List<CommonMultiLanguageViewModel> listModelObj_cnvsDesc_Lang, ref int countError)
	{
		int.TryParse(SysSeting.Get().DefaultLanguageID.ToString(), out var result);
		if (result <= 0)
		{
			result = 1065;
		}
		int lCID = Thread.CurrentThread.CurrentCulture.LCID;
		string text = "";
		if (string.IsNullOrWhiteSpace(conversation.cnvsDate))
		{
			countError++;
			text = text + Messages.CheckEmptycnvsDate + "<br>";
		}
		if (string.IsNullOrWhiteSpace(conversation.cnvsDay))
		{
			countError++;
			text = text + Messages.CheckEmptycnvsDay + "<br>";
		}
		if (string.IsNullOrWhiteSpace(conversation.cnvsTime))
		{
			countError++;
			text = text + Messages.CheckEmptycnvsTime + "<br>";
		}
		if (string.IsNullOrWhiteSpace(conversation.cnvsDesc))
		{
			countError++;
			text = text + Messages.CheckEmptycnvsDesc + "<br>";
		}
		else if (!checkMultiLanguage(conversation.cnvsDesc, listModelObj_cnvsDesc_Lang))
		{
			text = text + Messages.CheckcnvsDescLang + "<br>";
			countError++;
		}
		if (!conversation.cnvsTopicId.HasValue)
		{
			countError++;
			text = text + Messages.CheckEmptycnvsTopicId + "<br>";
		}
		if (!conversation.cnvsPersonId.HasValue)
		{
			countError++;
			text = text + Messages.CheckEmptycnvsPersonId + "<br>";
		}
		if (!conversation.cnvsUserId.HasValue)
		{
			countError++;
			text = text + Messages.CheckEmptycnvsUserId + "<br>";
		}
		if (!conversation.cnvsReferUserId.HasValue)
		{
			countError++;
			text = text + Messages.CheckEmptycnvsReferUserId + "<br>";
		}
		if (!conversation.cnvsStatusId.HasValue)
		{
			countError++;
			text = text + Messages.CheckEmptycnvsStatusId + "<br>";
		}
		else
		{
			CRMspSelectConversationForcedStatusBFCurr_Result cRMspSelectConversationForcedStatusBFCurr_Result = Enumerable.FirstOrDefault<CRMspSelectConversationForcedStatusBFCurr_Result>((IEnumerable<CRMspSelectConversationForcedStatusBFCurr_Result>)db.CRMspSelectConversationForcedStatusBFCurr(conversation.cnvsStatusId, conversation.cnvsProjectId, lCID, result, conversation.ConversationID));
			if (cRMspSelectConversationForcedStatusBFCurr_Result != null)
			{
				string arg = ((!string.IsNullOrEmpty(cRMspSelectConversationForcedStatusBFCurr_Result.Status)) ? cRMspSelectConversationForcedStatusBFCurr_Result.Status : "");
				countError++;
				text = text + string.Format(Messages.CheckForcedStatusBFCurr, arg) + "<br>";
			}
		}
		string cnvsDate = conversation.cnvsDate;
		if (!string.IsNullOrEmpty(cnvsDate) && !DateTime.TryParse(DateTimeClass.ConvertDateWOSlashToSlash(cnvsDate), out var _))
		{
			countError++;
			text = text + Messages.CheckFormatcnvsDate + "<br>";
		}
		string cnvsRemindDate = conversation.cnvsRemindDate;
		if (!string.IsNullOrEmpty(cnvsRemindDate) && !DateTime.TryParse(DateTimeClass.ConvertDateWOSlashToSlash(cnvsRemindDate), out var _))
		{
			countError++;
			text = text + Messages.CheckFormatcnvsRemindDate + "<br>";
		}
		string cnvsRemindDateForAllarm = conversation.cnvsRemindDateForAllarm;
