	[ValidateAntiForgeryToken]
	public ActionResult ActAttachDirFile([DataSourceRequest] DataSourceRequest request, HttpPostedFileBase[] FileUrlUpload)
	{
		string text = "";
		string text2 = "";
		try
		{
			if (FileUrlUpload != null)
			{
				bool flag = false;
				int maxFileCount = Configuration.MaxFileCount;
				if (FileUrlUpload.Length > maxFileCount)
				{
					string msgErrorMessageMaxSizeFile = Messages.msgErrorMessageMaxSizeFile;
					base.ModelState.AddModelError("error", string.Format(msgErrorMessageMaxSizeFile, maxFileCount));
					flag = true;
					text2 = string.Format(msgErrorMessageMaxSizeFile, maxFileCount) + "<br>";
				}
				HttpPostedFileBase[] array = FileUrlUpload;
				foreach (HttpPostedFileBase val in array)
				{
					val.ContentType.ToLower();
					object obj = ((val.FileName != null) ? Path.GetExtension(val.FileName).ToLower() : "");
					string arg = val.FileName ?? "";
					if (obj == null)
					{
						obj = "";
					}
					string text3 = ((string)obj).ToLower();
					text3 = text3.Replace(".", "");
					if (Configuration.MaliciousFileExtensions.Contains(text3))
					{
						flag = true;
						text2 = text2 + string.Format(Messages.msgErrorNotUploadFileByDue, arg) + Messages.msgErrorFileIsExecuted + "<br>";
					}
					int num = Configuration.MaxFileSizeForUploadMb * 1024 * 1024;
					if (val.ContentLength > num)
					{
						string fileFormatByteSize = CRM.General.IO.File.GetFileFormatByteSize(val.ContentLength);
						string fileFormatByteSize2 = CRM.General.IO.File.GetFileFormatByteSize(num);
						string msgErrorMessageMaxSizeFile2 = Messages.msgErrorMessageMaxSizeFile;
						flag = true;
						text2 = text2 + string.Format(Messages.msgErrorNotUploadFileByDue, arg) + string.Format(msgErrorMessageMaxSizeFile2, fileFormatByteSize, fileFormatByteSize2) + "<br>";
					}
				}
				if (flag)
				{
					text2 = "-1|" + text2;
					return Json(((IEnumerable)new string[1] { text2 }).ToDataSourceResult(request));
				}
				int userId = UserLogin.CurrentUser.UserId;
				_ = Configuration.AppType;
				array = FileUrlUpload;
				foreach (HttpPostedFileBase val2 in array)
				{
					val2.ContentType.ToLower();
					Path.GetExtension(val2.FileName).ToLower();
					string text4 = Configuration.HostTempFilesPath + "/" + Configuration.TmpFileDirectoryPath + "/" + userId;
					string text5 = base.Server.MapPath(text4);
					if (!System.IO.Directory.Exists(text5))
					{
						System.IO.Directory.CreateDirectory(text5);
						CRM.General.IO.Directory.SetFullControlForEveryOne(text5);
					}
					string text6 = Path.GetFileName(val2.FileName);
					if (text6 != null && text6.Length < Configuration.FileDirectoryTitleLength)
					{
						string text7 = Path.Combine(text5, text6);
						if (System.IO.File.Exists(text7))
						{
							text6 = DateTime.Now.ToString("yyyyMMdd-HHmmss") + "-" + text6;
							text7 = Path.Combine(text5, text6);
						}
						val2.SaveAs(text7);
						text = text7 + "|" + text6;
						continue;
					}
					text2 = text2 + Messages.IntmsgErrorLengthFileName + "<br>";
					text2 = "-1|" + text2;
					return Json(((IEnumerable)new string[1] { text2 }).ToDataSourceResult(request));
				}
			}
		}
		catch (Exception ex)
		{
			ErrorSignal.FromCurrentContext().Raise(ex);
			text2 = "-1|" + ex.Message;
			return Json(((IEnumerable)new string[1] { text2 }).ToDataSourceResult(request));
		}
		return Json(((IEnumerable)new string[1] { text }).ToDataSourceResult(request));
	}

	public string ActRemoveDirFile(string filePath)
	{
		string result = "-1";
		if (!string.IsNullOrWhiteSpace(filePath))
		{
			try
			{
				if (System.IO.File.Exists(filePath))
				{
					System.IO.File.Delete(filePath);
				}
				result = Messages.frmDeleteSuccessMessage;
			}
			catch (Exception e)
			{
				ErrorSignal.FromCurrentContext().Raise(e);
			}
		}
		return result;
	}

