	public bool DeleteFileByPath(string filePath, string fileName, string folderName)
	{
		bool result = false;
		if (!string.IsNullOrWhiteSpace(filePath) && !string.IsNullOrWhiteSpace(fileName) && !string.IsNullOrWhiteSpace(folderName))
		{
			try
			{
				string text = filePath.ToLower().Replace(Configuration.PathFtp.ToLower(), "");
				text = ((!text.Contains("/" + Configuration.IntmsgDirectoryPath.ToLower().Replace("/", "") + "/") && !text.Contains("\\" + Configuration.IntmsgDirectoryPath.ToLower().Replace("/", "") + "\\")) ? ((!text.Contains("/" + Configuration.KnlgTDirectoryPath.ToLower().Replace("/", "") + "/") && !text.Contains("\\" + Configuration.KnlgTDirectoryPath.ToLower().Replace("/", "") + "\\")) ? ((!text.Contains("/" + Configuration.DyDirectoryPath.ToLower().Replace("/", "") + "/") && !text.Contains("\\" + Configuration.DyDirectoryPath.ToLower().Replace("/", "") + "\\")) ? ((!text.Contains("/" + Configuration.FundDirectoryPath.ToLower().Replace("/", "") + "/") && !text.Contains("\\" + Configuration.FundDirectoryPath.ToLower().Replace("/", "") + "\\")) ? ((!text.Contains("/" + Configuration.UserDirectoryPath.ToLower().Replace("/", "") + "/") && !text.Contains("\\" + Configuration.UserDirectoryPath.ToLower().Replace("/", "") + "\\")) ? ((!text.Contains("/" + Configuration.CmsNewsDirectoryPath.ToLower().Replace("/", "") + "/") && !text.Contains("\\" + Configuration.CmsNewsDirectoryPath.ToLower().Replace("/", "") + "\\")) ? ((!text.Contains("/" + Configuration.StockSupplyDirectoryPath.ToLower().Replace("/", "") + "/") && !text.Contains("\\" + Configuration.StockSupplyDirectoryPath.ToLower().Replace("/", "") + "\\")) ? (Configuration.MainDirectoryPath + folderName + "/" + fileName) : (Configuration.MainDirectoryPath + Configuration.StockSupplyDirectoryPath + folderName + "/" + fileName)) : (Configuration.MainDirectoryPath + Configuration.CmsNewsDirectoryPath + folderName + "/" + Configuration.FilesDirectoryPath + "/" + fileName)) : (Configuration.MainDirectoryPath + Configuration.UserDirectoryPath + folderName + "/" + fileName)) : (Configuration.MainDirectoryPath + Configuration.FundDirectoryPath + folderName + "/" + fileName)) : (Configuration.MainDirectoryPath + Configuration.DyDirectoryPath + folderName + "/" + fileName)) : (Configuration.MainDirectoryPath + Configuration.KnlgTDirectoryPath + folderName + "/" + fileName)) : (Configuration.MainDirectoryPath + Configuration.IntmsgDirectoryPath + folderName + "/" + fileName));
				FacadeFTP facadeFTP = new FacadeFTP(Configuration.FacadeFtp);
				string destination = text;
				if (facadeFTP.Delete(Configuration.PathFtp, Configuration.UserNameFtp, Configuration.PasswordFtp, fileName, destination, Configuration.UsePassiveFtp))
				{
					result = true;
				}
			}
			catch (Exception e)
			{
				ErrorSignal.FromCurrentContext().Raise(e);
			}
		}
		return result;
	}

