				string text2 = "";
				text2 = new Random().Next(1000, 9999).ToString();
				SmsSendViewModel smsItem = new SmsSendViewModel
				{
					SmsSendBody = Labels.CompanyChangeMobileVerifyCode + ": " + text2,
