	[AjaxOnly]
	public string CopyMainPersonDataToCmp(int cmpId, int prsId)
	{
		string text = "";
		_ = UserLogin.CurrentUser.UserId;
		try
		{
			int.TryParse(SysSeting.Get().DefaultLanguageID.ToString(), out var result);
			if (result <= 0)
			{
				result = 1065;
			}
			int lCID = Thread.CurrentThread.CurrentCulture.LCID;
			string appType = Configuration.AppType;
			if (!UserLogin.IsUserAccess("frmCompanyI", "actCopyMainPersonDataToCmp", UserLogin.CurrentUser))
			{
				return Messages.ErrorNotAccess;
			}
			if (cmpId == 0)
			{
				return Messages.msgErrorNotSelectCompany;
			}
			if (prsId == 0)
			{
				return string.Format(Messages.msgErrorIsNotSelectedItem, Labels.cmpMainPersonId);
			}
			CRMspSelectCompanyPersonsByID_Result cRMspSelectCompanyPersonsByID_Result = Enumerable.FirstOrDefault<CRMspSelectCompanyPersonsByID_Result>((IEnumerable<CRMspSelectCompanyPersonsByID_Result>)db.CRMspSelectCompanyPersonsByID(prsId, lCID, result));
			if (cRMspSelectCompanyPersonsByID_Result != null)
			{
				string text2 = cRMspSelectCompanyPersonsByID_Result.prsMobile ?? "";
				if (!string.IsNullOrWhiteSpace(text2) && !string.IsNullOrEmpty(text2))
				{
					int mobNumLen = CRMIdeal.Classes.Helper.Setting.GetMobNumLen();
					bool mobNumLenNoCheck = CRMIdeal.Classes.Helper.Setting.GetMobNumLenNoCheck();
					if (text2.Length != mobNumLen && !mobNumLenNoCheck)
					{
						return Messages.CheckLebgthMobile;
					}
					if (text2.Length >= 2 && text2.Substring(0, 2) != "09" && !mobNumLenNoCheck)
					{
						return string.Format(Messages.ErrorInFormat, Labels.prsMobile);
					}
					string text3 = CantSaveDupCmpMobile(text2, cmpId);
					if (!string.IsNullOrEmpty(text3))
					{
						return text3;
					}
				}
				string text4 = cRMspSelectCompanyPersonsByID_Result.prsEmail ?? "";
				if (string.IsNullOrWhiteSpace(text4))
				{
					text4 = cRMspSelectCompanyPersonsByID_Result.prsEmailII ?? "";
				}
				if (!string.IsNullOrWhiteSpace(text4))
				{
					if (!Regex.IsMatch(text4, "\\w+([-+.']\\w+)*@\\w+([-.]\\w+)*\\.\\w+([-.]\\w+)*"))
					{
						return string.Format(Messages.ErrorInFormat, Labels.prsEmail);
					}
					string text5 = CantSaveDupCmpEmail(text4, cmpId);
					if (!string.IsNullOrEmpty(text5))
					{
						return text5;
					}
				}
				if (string.IsNullOrWhiteSpace(text2) && string.IsNullOrWhiteSpace(text4))
				{
					return Messages.msgErrorCmpMainPersonNotMobOrEmailInTrasferMobAndEmail;
				}
				int userId = UserLogin.CurrentUser.UserId;
				DateTime now = DateTime.Now;
				DateTime value = now;
				string registerDatePersian = now.ToString("yyyyMMdd", new PersianCulture());
				short value2 = short.Parse(now.ToString("MM", new PersianCulture()));
				short value3 = short.Parse(Financial.Get().Id.ToString());
				mct_I_Result mct_I_Result = Enumerable.FirstOrDefault<mct_I_Result>((IEnumerable<mct_I_Result>)_dbI.CRMspCopyCompanyPersonDataToCmp(cmpId, prsId, userId, value, registerDatePersian, value2, value3, appType));
				if (mct_I_Result != null)
				{
					_ = mct_I_Result.Result;
					int result2 = 0;
					int.TryParse(mct_I_Result.Result.ToString(), out result2);
					string text6 = "";
					switch (result2)
					{
					case -1:
						text6 = "<br/>" + Messages.msgErrorDupCmpMainPersonMobInTrasferMobAndEmail;
						break;
					case -2:
						text6 = "<br/>" + Messages.msgErrorDupCmpMainPersonEmailInTrasferMobAndEmail;
						break;
					case -3:
						text6 = "<br/>" + Messages.msgErrorDupCmpMainPersonEmailAndMobInTrasferMobAndEmail;
						break;
					}
					if (!string.IsNullOrWhiteSpace(text6))
					{
						return text6;
					}
				}
				return "1|" + text2 + "|" + text4;
			}
			return string.Format(Messages.msgErrorIsNotSelectedItem, Labels.cmpMainPersonId);
		}
		catch (DbEntityValidationException ex)
		{
			ErrorSignal.FromCurrentContext().Raise((Exception)(object)ex);
			return Messages.msgErrorRunFunction + "<br />" + ((Exception)(object)ex).Message;
		}
		catch (Exception ex2)
		{
			ErrorSignal.FromCurrentContext().Raise(ex2);
			return Messages.msgErrorRunFunction + "<br />" + ex2.Message;
		}
	}

