	[AjaxOnly]
	public JsonResult CalcCmpSupportCost(int cmpId, string baseCalcDate = "")
	{
		//IL_0206: Unknown result type (might be due to invalid IL or missing references)
		int.TryParse(SysSeting.Get().DefaultLanguageID.ToString(), out var result);
		if (result <= 0)
		{
			result = 1065;
		}
		int lCID = Thread.CurrentThread.CurrentCulture.LCID;
		List<WSspCalcCompanyPrdIndexPrice_Result> list = new List<WSspCalcCompanyPrdIndexPrice_Result>();
		try
		{
			_ = DateTime.Now;
			DateTime value = DateTime.Now;
			DateTime dateTime = default(DateTime);
			string text = "";
			try
			{
				if (!string.IsNullOrWhiteSpace(baseCalcDate))
				{
					text = PersianDate.GetFormatetdDate(baseCalcDate.Replace("/", ""));
					switch (lCID)
					{
					case 1065:
						dateTime = DateTime.Parse(text + " 00:00:00", new PersianCulture());
						baseCalcDate = dateTime.ToString("yyyyMMdd");
						break;
					case 1025:
						dateTime = DateTime.Parse(text + " 00:00:00", new CultureInfo("ar-SA"));
						baseCalcDate = dateTime.ToString("yyyyMMdd", new PersianCulture());
						break;
					default:
						dateTime = DateTime.Parse(text + " 00:00:00", new CultureInfo("en-US"));
						baseCalcDate = dateTime.ToString("yyyyMMdd", new PersianCulture());
						break;
					}
					value = dateTime;
					baseCalcDate = baseCalcDate.Replace("/", "").Replace("-", "").Replace("_", "")
						.Replace(".", "")
						.Replace(",", "")
						.Replace("\\", "");
				}
			}
			catch (Exception e)
			{
				ErrorSignal.FromCurrentContext().Raise(e);
			}
			list = Enumerable.ToList<WSspCalcCompanyPrdIndexPrice_Result>((IEnumerable<WSspCalcCompanyPrdIndexPrice_Result>)_dbI.WSspCalcCompanyPrdIndexPrice(cmpId, value, lCID, result));
			if (list == null)
			{
				list = new List<WSspCalcCompanyPrdIndexPrice_Result>();
			}
			else if (Enumerable.Any<WSspCalcCompanyPrdIndexPrice_Result>((IEnumerable<WSspCalcCompanyPrdIndexPrice_Result>)list))
			{
				foreach (WSspCalcCompanyPrdIndexPrice_Result item in list)
				{
					List<CalcCompanyPrdIndexPriceViewModel> list2 = new List<CalcCompanyPrdIndexPriceViewModel>();
					if (string.IsNullOrWhiteSpace(item.DetailCalcInfoJs))
					{
						continue;
					}
					list2 = new JavaScriptSerializer().Deserialize<List<CalcCompanyPrdIndexPriceViewModel>>(item.DetailCalcInfoJs);
					if (list2 == null || !Enumerable.Any<CalcCompanyPrdIndexPriceViewModel>((IEnumerable<CalcCompanyPrdIndexPriceViewModel>)list2))
					{
						continue;
					}
					foreach (CalcCompanyPrdIndexPriceViewModel item2 in list2)
					{
						string text2 = $"{item2.TotalAmount.GetValueOrDefault():N2}";
						text2 = text2.Replace(".00", "");
						item2.OrdDateStr = Labels.Year + (item2.OrdDate.HasValue ? item2.OrdDate.Value.ToString("yyyy") : "") + " = " + text2;
						item2.Formula = item2.OrdDateStr + "\n" + Labels.lblCalculationMethod + " = \n" + item2.Formula + "\n----------------------------\n";
						item2.Formula = item2.Formula.Replace(".00", "");
					}
					item.DetailCalcInfoJs = JsonConvert.SerializeObject(Enumerable.ToList<CalcCompanyPrdIndexPriceViewModel>((IEnumerable<CalcCompanyPrdIndexPriceViewModel>)list2));
				}
			}
		}
		catch (Exception e2)
		{
			ErrorSignal.FromCurrentContext().Raise(e2);
		}
		JsonResult jsonResult = Json(list, JsonRequestBehavior.AllowGet);
		jsonResult.MaxJsonLength = int.MaxValue;
		return jsonResult;
	}

