		string result = "";
		try
		{
			_dbII.CRMspUpdateCompanyCIds(UserLogin.CurrentUser.UserLastCId, cmpId);
			if (prsId != 0)
			{
				UpdateCompanyPersonCIds(cmpId, prsId);
			}
		}
		catch (Exception ex)
		{
			Public.InsExceptToElmah(ex);
			result = "Error: " + ex.Message;
		}
		return result;
	}

	[LoginAuthorize]
	public ActionResult PersonInsert(int id, int position = 0)
	{
		string text = "";
		string text2 = "";
		switch (position)
		{
		case 0:
			text = "frmCompanyI";
			text2 = "actprsInsert";
			break;
		case 1:
			text = "frmMain";
			text2 = "actcDailyTelInsertPrs";
			break;
		default:
			return RedirectToAction("Login", "Account", (object)new
			{
				area = "",
				d = DateTime.Now
			});
		}
		if (!UserLogin.IsUserAccess(text, text2, UserLogin.CurrentUser))
		{
			return RedirectToAction("Login", "Account", (object)new
			{
				area = "",
				d = DateTime.Now
			});
		}
		int.TryParse(SysSeting.Get().DefaultLanguageID.ToString(), out var result);
		if (result <= 0)
		{
			result = 1065;
		}
		_ = Thread.CurrentThread.CurrentCulture.LCID;
		if (_dbTbl.CrmCompany.Find(id) == null)
		{
			base.ViewBag.Error = Messages.prsErrorNotFindCompany;
		}
		CrmCompanyPersonsLanguageViewModel crmCompanyPersonsLanguageViewModel = new CrmCompanyPersonsLanguageViewModel();
		crmCompanyPersonsLanguageViewModel.UserId = UserLogin.CurrentUser.UserId;
		crmCompanyPersonsLanguageViewModel.prsFirstRegisterUserId = UserLogin.CurrentUser.UserId;
		crmCompanyPersonsLanguageViewModel.Year1 = short.Parse(Financial.Get().Id.ToString());
		crmCompanyPersonsLanguageViewModel.Month1 = short.Parse(DateTime.Now.ToString("MM", new PersianCulture()));
		crmCompanyPersonsLanguageViewModel.RegisterDate = DateTime.Now;
		crmCompanyPersonsLanguageViewModel.RegisterDatePersian = DateTime.Now.ToString("yyyyMMdd");
		crmCompanyPersonsLanguageViewModel.ImportDate = DateTime.Now.ToString("yyyyMMdd");
		crmCompanyPersonsLanguageViewModel.AddType = 2;
		crmCompanyPersonsLanguageViewModel.prsCompanyId = id;
		crmCompanyPersonsLanguageViewModel.prsCIds = ((UserLogin.CurrentUser != null) ? UserLogin.CurrentUser.UserLastCId : null)?.ToString();
		CRMspSelectCompanyById_Result companyById = CRMIdeal.Classes.Helper.Company.GetCompanyById(id);
		if (companyById != null)
		{
			int result2 = 0;
			int.TryParse(companyById.cmpKind.ToString(), out result2);
			crmCompanyPersonsLanguageViewModel.prsCompanyName = companyById.CompanyName ?? "";
		}
		PersonFullcombo_Lang();
		GetCompanyQuickRegisterDefSettingForPrs(id);
		return View(crmCompanyPersonsLanguageViewModel);
	}

