	public string ChkCantSaveDuplicatePrsFields(CrmCompanyPersonsLanguageViewModel person, ref int countError)
	{
		string text = "";
		int? userLastCId = ((UserLogin.CurrentUser != null) ? UserLogin.CurrentUser.UserLastCId : null);
		if (!string.IsNullOrEmpty(person.prsZipCode))
		{
			string text2 = CantSaveDupZipCode(person.prsZipCode, 2, person.CompanyPersonID);
			if (!string.IsNullOrEmpty(text2))
			{
				countError++;
				text = text + text2 + "<br/>";
			}
		}
		if (!string.IsNullOrEmpty(person.prsNationalCode))
		{
			string foundedPrsCIds = "";
			int foundedPrsId = 0;
			int foundedCmpId = 0;
			string text3 = CantSaveDupPrsNationalCode(ref foundedPrsCIds, ref foundedPrsId, person.prsNationalCode, person.CompanyPersonID, ref foundedCmpId);
			if (!string.IsNullOrEmpty(text3))
			{
				if (Enumerable.FirstOrDefault<string>((IEnumerable<string>)Enumerable.ToList<string>((IEnumerable<string>)foundedPrsCIds.Split(new char[1] { ',' })), (Func<string, bool>)((string x) => x == userLastCId.ToString())) == null && Center.HaveModule && Center.TotalCnt != 1)
				{
					List<SelectListItem> list = new List<SelectListItem>();
					string text4 = CRMIdeal.Classes.Helper.User.AccessUserToCIds(foundedPrsCIds);
					string text5 = "";
					text5 = (string.IsNullOrWhiteSpace(text4) ? string.Format(Messages.msgFoundCompanyInOtherCenterAskToAddUserNoAccess, Center.GetNames(userLastCId.ToString())) : string.Format(Messages.msgFoundCompanyInOtherCenterAskToAdd, Center.GetNames(text4), Center.GetNames(userLastCId.ToString())));
					list.Add(new SelectListItem
					{
						Text = "ExistInOtherCenter",
						Value = text5
					});
					list.Add(new SelectListItem
					{
						Text = "FPrsId",
						Value = foundedPrsId.ToString()
					});
					list.Add(new SelectListItem
					{
						Text = "FCIds",
						Value = foundedPrsCIds.ToString()
					});
					return JsonConvert.SerializeObject(list);
				}
				countError++;
				text = text + text3 + "<br/>";
			}
		}
		return text;
	}

	[DynamicAuthorize(ControllerName = "frmDefineCompanyPerson", ActionName = "actInsert")]
	public ActionResult PersonMoreInfoInsert(int id)
	{
		int result = 0;
		if (UserLogin.CurrentUser != null)
		{
			int.TryParse(UserLogin.CurrentUser.UserLastCId.ToString(), out result);
		}
		CrmCompany crmCompany = _dbTbl.CrmCompany.Find(id);
		if (crmCompany == null)
		{
			base.ViewBag.Error = Messages.prsErrorNotFindCompany;
		}
		CrmCompanyPersonsLanguageViewModel crmCompanyPersonsLanguageViewModel = new CrmCompanyPersonsLanguageViewModel();
		crmCompanyPersonsLanguageViewModel.UserId = UserLogin.CurrentUser.UserId;
		crmCompanyPersonsLanguageViewModel.prsFirstRegisterUserId = UserLogin.CurrentUser.UserId;
		crmCompanyPersonsLanguageViewModel.Year1 = short.Parse(Financial.Get().Id.ToString());
		crmCompanyPersonsLanguageViewModel.Month1 = short.Parse(DateTime.Now.ToString("MM", new PersianCulture()));
		crmCompanyPersonsLanguageViewModel.RegisterDate = DateTime.Now;
		crmCompanyPersonsLanguageViewModel.RegisterDatePersian = DateTime.Now.ToString("yyyyMMdd");
		crmCompanyPersonsLanguageViewModel.ImportDate = DateTime.Now.ToString("yyyyMMdd");
		crmCompanyPersonsLanguageViewModel.AddType = 2;
		crmCompanyPersonsLanguageViewModel.prsCompanyId = id;
		crmCompanyPersonsLanguageViewModel.prsCountryId = crmCompany.cmpCountryId;
		crmCompanyPersonsLanguageViewModel.prsProvinceId = crmCompany.cmpProvinceId;
		crmCompanyPersonsLanguageViewModel.prsCityId = crmCompany.cmpCityId;
		prsMoreInfoSetUserNameDate_lang(new CrmCompanyPersons());
		crmCompanyPersonsLanguageViewModel.prsCIds = result.ToString();
		crmCompanyPersonsLanguageViewModel.prsFOInfo = CRMIdeal.Classes.Helper.Company.GetFoInfoJsonByName("", crmCompanyPersonsLanguageViewModel.prsCIds);
		PersonFullcombo_Lang();
		GetCompanyQuickRegisterDefSettingForPrs(id);
		return View(crmCompanyPersonsLanguageViewModel);
	}

