		string importDate = person.ImportDate;
		importDate = (person.ImportDateTime.HasValue ? person.ImportDateTime.Value.ToString("yyyy/MM/dd HH:mm:ss") : "");
		base.ViewBag.ImportDate = importDate;
		CRMspSelectUsersByIds_Result cRMspSelectUsersByIds_Result2 = Enumerable.FirstOrDefault<CRMspSelectUsersByIds_Result>((IEnumerable<CRMspSelectUsersByIds_Result>)list, (Func<CRMspSelectUsersByIds_Result, bool>)((CRMspSelectUsersByIds_Result c) => c.UserId == person.UserId));
		string text2 = Labels.prsUserId + ": " + ((cRMspSelectUsersByIds_Result2 != null) ? (cRMspSelectUsersByIds_Result2.LName + ((cRMspSelectUsersByIds_Result2.FName != null) ? (" " + cRMspSelectUsersByIds_Result2.FName) : "")) : "");
		string registerDatePersian = person.RegisterDatePersian;
		_ = person.RegisterDate;
		registerDatePersian = person.RegisterDate.ToString("yyyy/MM/dd HH:mm:ss");
		base.ViewBag.RegisterDateStr = registerDatePersian;
		if (string.IsNullOrEmpty(person.AppType))
		{
			person.AppType = Configuration.AppType;
		}
		string text3 = Labels.AppType + ": " + Configuration.GetAppType(person.AppType);
