		crmCompanyPersonsTemplateLanguageViewModel.Year1 = short.Parse(Financial.Get().Id.ToString());
		crmCompanyPersonsTemplateLanguageViewModel.Month1 = short.Parse(now.ToString("MM", new PersianCulture()));
		crmCompanyPersonsTemplateLanguageViewModel.RegisterDate = now;
		crmCompanyPersonsTemplateLanguageViewModel.RegisterDatePersian = now.ToString("yyyyMMdd");
		crmCompanyPersonsTemplateLanguageViewModel.ImportDate = now.ToString("yyyyMMdd");
		crmCompanyPersonsTemplateLanguageViewModel.ImportDateTime = now;
