	[HttpGet]
	[AjaxOnly]
	public JsonResult GetCompanyPersonPasswordMoreInfo(int companyPersonId, string inputPassword, int mode)
	{
		if (!UserLogin.IsUserAccess("frmDefineCompany", "actShowCmpPassword"))
		{
			return Json(new
			{
				message = Messages.ErrorNotAccess,
				data = string.Empty
			}, JsonRequestBehavior.AllowGet);
		}
		CrmCompanyPersons crmCompanyPersons = _dbTbl.CrmCompanyPersons.Find(companyPersonId);
		if (crmCompanyPersons == null || string.IsNullOrEmpty(crmCompanyPersons.prsPassword))
		{
			return Json(new
			{
				data = string.Empty
			}, JsonRequestBehavior.AllowGet);
		}
		string obj = ((!string.IsNullOrEmpty(inputPassword)) ? XorCipher.EncryptByPublicKey(inputPassword) : null);
		string text = ((!string.IsNullOrEmpty(crmCompanyPersons.prsPassword)) ? XorCipher.DecryptByPublicKey(crmCompanyPersons.prsPassword) : null);
		bool num = obj == crmCompanyPersons.prsPassword;
		bool flag = inputPassword == crmCompanyPersons.prsPassword;
		if (!num && !flag)
		{
			return Json(new
			{
				data = inputPassword
			}, JsonRequestBehavior.AllowGet);
		}
		return Json(new
		{
			data = ((mode == 1) ? text : crmCompanyPersons.prsPassword)
		}, JsonRequestBehavior.AllowGet);
	}

