					crmProjectsInsertViewModel.prjNumR = Enumerable.FirstOrDefault<long>(db.Database.SqlQuery<long>(string.Format("Select dbo.CRMfnReturnProjectNumR({0},'{1}')", crmProjectsInsertViewModel.prjCompanyId, ""), Array.Empty<object>()));
