					{
						prjToDoTimeStr = lCID switch
						{
							1065 => DateTime.Now.ToString("yyyy/MM/dd", new PersianCulture()), 
							1025 => DateTime.Now.ToString("yyyy/MM/dd", new CultureInfo("ar-SA")), 
							_ => DateTime.Now.ToString("yyyy/MM/dd", new CultureInfo("en-US")), 
						};
					}
